  sort_order, status, published_at, seo_title, seo_description)
values ('web', 'E-commerce', 'ecommerce', 'Stores built for speed and checkout.', 'E-commerce Stores Built for Speed, Search and Checkout', 'We build online stores that load fast, rank well and make buying easy — then connect them to the email, ads and automation that bring shoppers back. Shopify, WooCommerce or headless, depending on what your business needs.', 'shopping-cart', array['Shopify, WooCommerce or headless Next.js builds', 'Product page and checkout optimization', 'Multi-currency and international setup', 'Payment gateways (Stripe, PayPal, Razorpay and others)', 'Inventory, shipping and ERP integrations', 'Product schema and SEO', 'Abandoned cart and post-purchase email flows']::text[],
