  sort_order, status, published_at, seo_title, seo_description)
values ('ai', 'AI Automation', 'ai-automation', 'AI steps inside everyday workflows.', 'AI Automation for the Work Rules Alone Can''t Handle', 'Some tasks need a little judgment — reading an email to understand what someone wants, summarizing a long document, drafting a reply. We build AI steps into your workflows for exactly those tasks, with checks and human review where it matters.', 'bot', array['Workflow analysis and opportunity ranking', 'AI classification, extraction and summarization steps', 'Draft generation for emails and responses', 'Human-in-the-loop approval steps', 'Integration with email, CRM, chat and helpdesk', 'Logging, monitoring and error alerts']::text[],
