insert into public.services (pillar, name, slug, short_description, hero_heading, intro, icon, features,
  sort_order, status, published_at, seo_title, seo_description)
values ('ai', 'Business Automation', 'business-automation', 'Connect tools and stop copy-pasting.', 'Business Automation That Connects Your Tools', 'Most teams lose hours to copying data between tools, chasing updates and sending the same messages. We connect your systems so information moves on its own — and every lead, order and request gets handled on time.', 'workflow', array['Lead capture and routing automation', 'CRM setup and integration (HubSpot, Zoho, Pipedrive and others)', 'Order, invoice and fulfillment workflows', 'Approval and notification flows', 'Scheduled reports and alerts', 'WhatsApp, Slack and email notifications', 'Documentation and monitoring']::text[],
  20, 'PUBLISHED', '2026-10-04T00:00:00Z', 'Business Automation Services — Workflow & CRM Automation | Pytron Digital', 'Business automation that connects your CRM, forms, store, accounting and chat tools: lead routing, follow-ups, approvals and reports that run without manual work.')
on conflict (pillar, slug) do nothing;
insert into public.services (pillar, name, slug, short_description, hero_heading, intro, icon, features,
  sort_order, status, published_at, seo_title, seo_description)
values ('ai', 'Document Processing', 'document-processing', 'Extract data from PDFs, scans and forms.', 'Document Processing That Turns Paperwork Into Data', 'Invoices, application forms, contracts, certificates, scanned records — if your team reads documents to type information into another system, we can automate most of that work with OCR and AI extraction, plus validation and review.', 'scan-text', array['OCR for scanned and photographed documents', 'AI field extraction for invoices, forms and contracts', 'Classification of mixed document types', 'Validation rules and confidence thresholds', 'Human review interface', 'Export to accounting, CRM, ERP or databases', 'Searchable document archive']::text[],
  30, 'PUBLISHED', '2026-10-04T00:00:00Z', 'AI Document Processing — Data Extraction from PDFs & Scans | Pytron Digital', 'AI document processing that extracts data from invoices, forms, IDs, contracts and scanned PDFs, validates it and sends it to your systems — with review where needed.')
on conflict (pillar, slug) do nothing;
insert into public.services (pillar, name, slug, short_description, hero_heading, intro, icon, features,
  sort_order, status, published_at, seo_title, seo_description)
values ('ai', 'AI Integrations', 'ai-integrations', 'Assistants and AI features in your product.', 'AI Integrations That Make Your Product and Website More Useful', 'We add AI where it genuinely helps your customers or team: assistants that answer from your own approved content, AI features inside your web app, and secure connections between AI models and the systems you already run.', 'plug', array['Website and in-app assistants grounded in your content', 'Retrieval over documents, help centers and databases', 'AI search and recommendations', 'Summarization and drafting features', 'Integration with CRM, helpdesk and messaging', 'Evaluation, monitoring and cost controls']::text[],
  40, 'PUBLISHED', '2026-10-04T00:00:00Z', 'AI Integrations — Assistants, Chatbots & AI Features | Pytron Digital', 'AI integrations for websites and products: assistants that answer from your own content, AI features inside your app and connections between AI models and your systems.')
on conflict (pillar, slug) do nothing;

